public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    if (nums == null) {
        return res;
    }
    int n = nums.length;
    if (n == 0) {
        res.add(new ArrayList<>());
        return res;
    }
    boolean[] used = new boolean[n];
    List<Integer> current = new ArrayList<>(n);
    class Backtracker {
        void backtrack() {
            if (current.size() == n) {
                res.add(new ArrayList<>(current));
                return;
            }
            for (int i = 0; i < n; i++) {
                if (!used[i]) {
                    used[i] = true;
                    current.add(nums[i]);
                    backtrack();
                    current.remove(current.size() - 1);
                    used[i] = false;
                }
            }
        }
    }
    new Backtracker().backtrack();
    return res;
}

