public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate basic inputs
    if (n <= 0) {
        throw new IllegalArgumentException("Size n must be positive");
    }
    if (start == null || end == null) {
        throw new IllegalArgumentException("Start and end coordinates cannot be null");
    }
    if (start.length != n || end.length != n) {
        throw new IllegalArgumentException("Start and end coordinates must have length equal to n");
    }
    // If start equals end, travel is trivially possible
    boolean same = true;
    for (int i = 0; i < n; i++) {
        if (start[i] != end[i]) {
            same = false;
            break;
        }
    }
    if (same) {
        return "can be travelled";
    }

    // Build adjacency map from coordinates to neighbors
    java.util.Map<String, java.util.List<String>> adjacency = new java.util.HashMap<>();
    if (paths != null) {
        for (int[] path : paths) {
            if (path == null || path.length != 2 * n) {
                throw new IllegalArgumentException("Each path must contain exactly 2*n integers");
            }
            StringBuilder sb1 = new StringBuilder();
            StringBuilder sb2 = new StringBuilder();
            for (int i = 0; i < n; i++) {
                if (i > 0) {
                    sb1.append(',');
                    sb2.append(',');
                }
                sb1.append(path[i]);
                sb2.append(path[i + n]);
            }
            String coord1 = sb1.toString();
            String coord2 = sb2.toString();
            adjacency.computeIfAbsent(coord1, k -> new java.util.ArrayList<>()).add(coord2);
            adjacency.computeIfAbsent(coord2, k -> new java.util.ArrayList<>()).add(coord1);
        }
    }

    // Convert start and end to string keys
    StringBuilder sbStart = new StringBuilder();
    StringBuilder sbEnd = new StringBuilder();
    for (int i = 0; i < n; i++) {
        if (i > 0) {
            sbStart.append(',');
            sbEnd.append(',');
        }
        sbStart.append(start[i]);
        sbEnd.append(end[i]);
    }
    String startKey = sbStart.toString();
    String endKey = sbEnd.toString();

    // If start or end not present in adjacency map, they might still be isolated nodes
    // but if start==end we already handled. If start not in map, cannot travel unless start==end
    if (!adjacency.containsKey(startKey)) {
        return "cannot be travelled";
    }

    // BFS to find connectivity
    java.util.Queue<String> queue = new java.util.LinkedList<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        if (current.equals(endKey)) {
            return "can be travelled";
        }
        java.util.List<String> neighbors = adjacency.getOrDefault(current, java.util.Collections.emptyList());
        for (String neighbor : neighbors) {
            if (!visited.contains(neighbor)) {
                visited.add(neighbor);
                queue.add(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

