public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    if (k <= 0) {
        return false;
    }
    int[] count = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k; // handle negative numbers
        count[rem]++;
    }
    // Remainder 0 must be even
    if (count[0] % 2 != 0) {
        return false;
    }
    // If k is even, remainder k/2 must also be even
    if (k % 2 == 0) {
        if (count[k / 2] % 2 != 0) {
            return false;
        }
    }
    // For other remainders, counts must match complementary remainders
    for (int r = 1; r <= k / 2; r++) {
        if (k % 2 == 0 && r == k / 2) {
            continue; // already handled
        }
        if (count[r] != count[k - r]) {
            return false;
        }
    }
    return true;
