public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        // Can start at step 1 (top) with no cost
        return 0;
    }
    // dp[i] = minimum cost to reach step i
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        int costPrev = cost[i - 1];
        dp[i] = costPrev + Math.min(dp[i - 1], dp[i - 2]);
    }
    return Math.min(dp[n], dp[n - 1]);
}

