public static int squarePermutations(int[] A) {
    if (A == null || A.length == 0) return 0;
    int n = A.length;
    java.util.Arrays.sort(A);
    boolean[] visited = new boolean[n];
    java.util.Map<Long, Integer> memo = new java.util.HashMap<>();
    int fullMask = (1 << n) - 1;

    java.util.function.IntBinaryOperator isSquare = (x, y) -> {
        int sum = x + y;
        int r = (int) Math.sqrt(sum);
        return r * r == sum ? 1 : 0;
    };

    java.util.function.IntUnaryOperator dfs = new java.util.function.IntUnaryOperator() {
        @Override
        public int applyAsInt(int mask) {
            return dfs(mask, -1);
        }

        private int dfs(int mask, int lastIndex) {
            if (mask == fullMask) return 1;
            long key = ((long) mask << 32) | (lastIndex + 1);
            Integer cached = memo.get(key);
            if (cached != null) return cached;
            int total = 0;
            for (int i = 0; i < n; i++) {
                if (visited[i]) continue;
                if (i > 0 && A[i] == A[i - 1] && !visited[i - 1]) continue;
                if (lastIndex == -1 || isSquare.applyAsInt(A[lastIndex], A[i]) == 1) {
                    visited[i] = true;
                    total += dfs(mask | (1 << i), i);
                    visited[i] = false;
                }
            }
            memo.put(key, total);
            return total;
        }
    };

    return dfs.applyAsInt(0);
}

